#pragma config(Sensor, dgtl1, bumper, sensorTouch)
#pragma config(Motor, port1, testMotor, tmotorVex393_HBridge, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
ENGR 10 Week 1 - Practice program 3
Bumper switch in Digital port 1.
The motor spins until the bumper is pressed, then stops.
When the bumper is released, the motor spins again in the REVERSE direction.
Pressing again stops it, releasing reverses it again, and so on.
*/
task main()
{
	int speed = 63;          // motor power
	int direction = 1;       // 1 = forward, -1 = reverse

	while(true)
	{
		// spin until the bumper is pressed
		motor[testMotor] = speed * direction;
		while(SensorValue[bumper] == 0)
		{
			wait1Msec(10);
		}

		// pressed: stop and stay stopped while it is held down
		motor[testMotor] = 0;
		while(SensorValue[bumper] == 1)
		{
			wait1Msec(10);
		}

		// released: switch direction for the next spin
		direction = -direction;
		wait1Msec(50);       // ignore switch bounce
	}
}
